/bin/bash -lc "node <<'NODE'
const ts = require('/opt/typescript/lib/typescript.js');
const fs = require('fs');
const path = require('path');
const context = JSON.parse(fs.readFileSync('/work/context.json', 'utf8'));
const roots = context.files.filter(f=>f.endsWith('.ts')).map(f=>path.join(context.workspace, f));
const cfg = ts.parseConfigFileTextToJson('tsconfig.json', fs.readFileSync('tsconfig.json','utf8'));
const options = ts.convertCompilerOptionsFromJson(cfg.config.compilerOptions, context.workspace).options;
const program = ts.createProgram(roots, options);
const checker = program.getTypeChecker();
const source = program.getSourceFile(path.join(context.workspace,'src/utilities/typeFromAST.ts'));
const decl = source.statements.find(n=>ts.isFunctionDeclaration(n) && n.name.text==='typeFromAST');
const target = checker.getSymbolAtLocation(decl.name);
const rows=[];
const excluded=[];
for(const f of roots){
const sf=program.getSourceFile(f);
function walk(n){
if(ts.isIdentifier(n)){
let sym=checker.getSymbolAtLocation(n);
if(sym && (sym.flags & ts.SymbolFlags.Alias))sym=checker.getAliasedSymbol(sym);
if(sym===target){
const start=sf.getLineAndCharacterOfPosition(n.getStart(sf));
const end=sf.getLineAndCharacterOfPosition(n.getEnd());
const row={target:'typeFromAST',file:path.relative(context.workspace,f),line:start.line+1,column:start.character,end_line:end.line+1,end_column:end.character};
if(ts.isFunctionDeclaration(n.parent)&&n.parent.name===n)excluded.push(row);else rows.push(row);
}
}
ts.forEachChild(n,walk);
}walk(sf);
}
rows.sort((a,b)=>a.file.localeCompare(b.file)||a.line-b.line||a.column-b.column);
console.log(JSON.stringify({references:rows,excludedDeclarations:excluded},null,2));
NODE"
